/**
 * Order struct from the AtomicSwap contract
 */
export interface AtomicSwapOrder {
  seller: Hex
  sellerIBCAddr: string
  sellerChannel: string
  sellToken: Hex
  sellAmount: bigint
  buyToken: Hex
  buyAmount: bigint
  isActive: boolean
  isCancelled: boolean
  whitelistedBuyer: Hex
}

/**
 * Order with ID for display purposes
 */
export interface AtomicSwapOrderWithId extends AtomicSwapOrder {
  id: bigint
}

